function createCatalogV10(){return BASE_CATALOG_V10.map(s=>({...s,moodIds:[...s.moodIds]}));}
function upgradeCatalogV10(target){
  if(!target.settings||typeof target.settings!=='object') target.settings={theme:'carbono'};
  if(Number(target.settings.baseCatalogVersion)>=10)return false;
  // Preserve every record and all user-created strategies. Never rewrite historical snapshots.
  for(const s of target.strategies){
    const old=LEGACY_BASELINE_V9[s.id];
    if(!old||s.retiredByCatalog)continue;
    const same=s.createdAt==='base'&&s.activityId===old[0]&&s.text===old[1]&&s.kind===old[2]&&
      Array.isArray(s.moodIds)&&JSON.stringify([...s.moodIds].sort())===JSON.stringify(old[3]);
    if(same){s.active=false;s.retiredByCatalog=10;}
  }
  const ids=new Set(target.strategies.map(s=>s.id));
  for(const base of createCatalogV10()){if(!ids.has(base.id))target.strategies.push(base);}
  target.settings.baseCatalogVersion=10;
  return true;
}
function seedData(){
  const moods={};
  Object.entries(MOOD_NAMES).forEach(([aid,names])=>{moods[aid]=names.map(n=>({id:'m_'+n.toLowerCase().replace(/\s+/g,'_'),name:n,icon:MOOD_ICONS[n]||'circle',active:true}));});
  return {schemaVersion:2,moods,strategies:createCatalogV10(),records:[],settings:{theme:'carbono',baseCatalogVersion:10},createdAt:new Date().toISOString()};
}

let db;
let storageFault=false;
try{
  const saved=localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_STORAGE_KEY);
  db=saved?JSON.parse(saved):seedData();
  if(!db||db.schemaVersion!==2||!Array.isArray(db.records)||!Array.isArray(db.strategies)||!db.moods) throw new Error('invalid');
}catch(e){db=seedData();storageFault=true;}
if(!db.settings||typeof db.settings!=='object') db.settings={theme:'carbono'};
if(!THEME_PRESETS.some(t=>t.id===db.settings.theme)) db.settings.theme='carbono';
const catalogMigrated=upgradeCatalogV10(db);
