const ui={view:'home',homeMode:'registrar',recordId:null,historyYear:Number(today.date.slice(0,4)),historyMonth:Number(today.date.slice(5,7))-1,historyDay:null,addMood:false,editMoodId:null,addingStrategy:false,editStrategyId:null,managerFilter:'all',feedbackExpanded:false,quickDetails:false,quickExpanded:false,quickTiming:'agora',strategyTiming:'agora',retroDate:null,retro:false};
const main=document.getElementById('main');const navigation=document.getElementById('navigation');const themeModal=document.getElementById('theme-modal');const themeBackdrop=document.getElementById('theme-backdrop');const themeOptions=document.getElementById('theme-options');const themeClose=document.getElementById('theme-close');let toastTimer;let themeOpener=null;
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,3700);}
function toastAction(message,actionText,callback){
  const t=document.getElementById('toast');clearTimeout(toastTimer);t.replaceChildren();
  const span=document.createElement('span');span.textContent=message;
  const button=document.createElement('button');button.type='button';button.className='toast-undo';button.textContent=actionText;
  button.addEventListener('click',()=>{clearTimeout(toastTimer);t.hidden=true;callback();},{once:true});
  t.append(span,button);t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,7000);
}
function undoStrategyRemoval(recordId,sourceId){const r=db.records.find(x=>x.id===recordId);if(!r)return;r.excludedStrategyIds=r.excludedStrategyIds.filter(id=>id!==sourceId);touch(r);if(ui.recordId===recordId&&ui.view==='strategies')render();toast('Estratégia restaurada nesta preparação.');}
function currentTheme(){return db.settings?.theme||'carbono';}
function applyTheme(){const preset=THEME_PRESETS.find(t=>t.id===currentTheme())||THEME_PRESETS[0];document.documentElement.setAttribute('data-theme',preset.id);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',preset.themeColor);}
function renderThemeOptions(){if(!themeOptions)return;const active=currentTheme();themeOptions.innerHTML=THEME_PRESETS.map(t=>`<button type="button" class="theme-option ${t.id===active?'active':''}" data-action="set-theme" data-id="${t.id}"><div class="theme-preview" style="--swatch-1:${t.swatch[0]};--swatch-2:${t.swatch[1]};--swatch-3:${t.swatch[2]}"><span class="p1"></span><span class="p2"></span><span class="p3"></span><span class="p4"></span></div><div><div class="theme-name">${t.name}</div><div class="theme-desc">${t.desc}</div></div></button>`).join('');}
function openThemeModal(){themeOpener=document.activeElement;renderThemeOptions();themeBackdrop.hidden=false;themeModal.hidden=false;document.body.classList.add('modal-open');themeClose?.focus();}
function closeThemeModal(){themeBackdrop.hidden=true;themeModal.hidden=true;document.body.classList.remove('modal-open');if(themeOpener?.isConnected)themeOpener.focus();themeOpener=null;}
function chooseTheme(id){if(!THEME_PRESETS.some(t=>t.id===id))return;db.settings.theme=id;persist();applyTheme();renderThemeOptions();toast('Tema atualizado.');}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));storageFault=false;return true;}catch(e){storageFault=true;toast('Erro ao salvar. Exporte um backup e verifique o espaço disponível.');return false;}}
function rec(){return db.records.find(x=>x.id===ui.recordId)||null;}
function activityMoods(id,activeOnly=true){return (db.moods[id]||[]).filter(m=>!activeOnly||m.active);}
