function newRecord(activityId,date='',time=null,entryMode='preparacao'){const now=nowLocal();const entry={id:uid(),activityId,date:date||now.date,time:time===null?now.time:time,entryMode,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:'andamento',initialMoods:[],duringMoods:[],finalMoods:[],excludedStrategyIds:[],preventionSelectedIds:[],temporaryStrategies:[],strategies:[],preparationSaved:false,result:null,durationMinutes:null,notes:''};db.records.push(entry);persist();ui.recordId=entry.id;ui.view=entryMode==='registro'?'quick':'moods';ui.quickDetails=false;ui.quickExpanded=false;ui.quickTiming='agora';ui.strategyTiming='agora';ui.addMood=false;ui.retro=false;render();}
