function renderMoods(){const r=rec();if(!r)return renderHome();const a=ACT(r.activityId);const moods=activityMoods(a.id);return `${header(a)}<div class="tiles">${moods.map(m=>{const active=r.initialMoods.some(x=>x.id===m.id);return `<button type="button" class="tile mood-tile ${active?'active':''}" data-tone="${MOOD_TONES[m.name]||'violet'}" aria-pressed="${active}" data-action="toggle-initial-mood" data-id="${esc(m.id)}"><span class="tile-symbol">${icon(m.icon||MOOD_ICONS[m.name]||'circle')}</span><span class="title">${esc(m.name)}</span>${icon('check','checkmark')}</button>`;}).join('')}</div><div class="actions"><button class="btn" data-action="to-strategies" ${!r.initialMoods.length?'disabled':''}>Ver estratégias ${icon('right')}</button><button class="btn secondary" data-action="toggle-add-mood">${icon('plus')} Adicionar mood</button></div>${ui.addMood?moodEditorMarkup(null,'new'):''}<div class="mt-sm" style="text-align:center"><button class="muted-link" data-action="mood-manager">Gerenciar moods</button></div>`;}
function moodEditorMarkup(m,scope){return `<form class="form-card mt-sm" data-form="save-mood" data-scope="${scope}" ${m?`data-id="${esc(m.id)}"`:''}><label class="form-label">${m?'Editar mood':'Novo mood'}<input name="name" maxlength="45" placeholder="Nome do mood" value="${esc(m?.name||'')}" required autocomplete="off"></label><div class="split"><button type="submit" class="btn">Salvar</button><button type="button" class="btn secondary" data-action="cancel-edit">Cancelar</button></div></form>`;}

function quickOptions(r){
  const seen=new Set(),options=[];
  for(const s of db.strategies.filter(s=>s.active&&s.activityId===r.activityId)){
    const key=nameKey(s.text);if(seen.has(key))continue;seen.add(key);options.push(s);
  }
  // Recorded strategies must remain visible even if later removed from the catalog.
  for(const st of r.strategies||[]){
    const key=nameKey(st.text);if(!seen.has(key)){
      options.push({id:st.sourceId||st.id,text:st.text,kind:st.kind,timing:st.timing||'agora'});
      seen.add(key);
    }
  }
  return options;
}

function quickChecked(r,s){return r.strategies.some(x=>x.done&&(x.sourceId===s.id||nameKey(x.text)===nameKey(s.text)));}
function quickRating(r,s){return r.strategies.find(x=>x.done&&(x.sourceId===s.id||nameKey(x.text)===nameKey(s.text)));}
function quickItem(r,s){const checked=quickChecked(r,s);const st=checked?quickRating(r,s):null;return `<div class="quick-item ${checked?'checked':''}"><label class="quick-check"><input type="checkbox" data-action="quick-check" data-id="${esc(s.id)}" ${checked?'checked':''}><span>${esc(s.text)}</span></label>${checked?`<div class="quick-rating" aria-label="Avaliação da estratégia">${[['yes','Ajudou'],['no','Não ajudou'],['unsure','Não sei']].map(([v,label])=>`<button class="quick-rating-btn ${st?.helped===(v==='yes'?true:v==='no'?false:'incerto')?'active':''}" data-action="quick-rate" data-id="${esc(st.id)}" data-value="${v}" type="button">${label}</button>`).join('')}</div>`:''}</div>`;}
