 'back':()=>{switch(ui.view){case 'quick':view('home');break;case 'moods':view('home');break;case 'strategies':view('moods');break;case 'execute':view('strategies');break;case 'feedback':view('execute');break;case 'retro':view('history');break;case 'record':case 'record-edit':fromRecordToHistory();break;default:view('home');}},
