 'edit-mood':el=>{ui.editMoodId=ui.editMoodId===el.dataset.id?null:el.dataset.id;ui.addMood=false;render();},
 'toggle-mood-active':el=>{const r=rec();const m=activityMoods(r.activityId,false).find(x=>x.id===el.dataset.id);if(!m)return;if(m.active&&!window.confirm('Ocultar este mood das próximas seleções? Os registros antigos continuam intactos.'))return;m.active=!m.active;persist();render();},
 'toggle-add-strategy':()=>{ui.addingStrategy=!ui.addingStrategy;render();if(ui.addingStrategy)requestAnimationFrame(()=>document.querySelector('.strategy-editor-anchor')?.scrollIntoView({behavior:'smooth',block:'center'}));},
 'manager-add-strategy':()=>{ui.addingStrategy=!ui.addingStrategy;ui.editStrategyId=null;render();},
 'exclude-strategy':el=>{const r=rec();if(!r)return;const sourceId=el.dataset.id;const rid=r.id;if(!r.excludedStrategyIds.includes(sourceId)){r.excludedStrategyIds.push(sourceId);touch(r);render();toastAction('Estratégia retirada desta preparação.','Desfazer',()=>undoStrategyRemoval(rid,sourceId));}},
 'save-preparation':()=>savePreparation(),
  'select-prevention':()=>{},
 'strategy-manager':()=>{ui.managerFilter='all';view('strategy-manager');},
